sql.where:

    AND session_id = #{sessionId}


    AND session_name = #{sessionName}


    AND user_id = #{userId}


    AND user_name = #{userName}


    AND status = #{status}


    AND create_time >= #{createTimeBegin}


    AND create_time <= #{createTimeEnd}


    AND update_time >= #{updateTimeBegin}


    AND update_time <= #{updateTimeEnd}

AND del_flag = '0'
